package com.bank.largestnumber;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Builds the largest concatenated branch identifier for National Bank of India.
public class LargestNumberBuilder {
    private static final Logger log = Logger.getLogger(LargestNumberBuilder.class.getName());

    // Largest number by concatenation. O(n log n) comparisons.
    public String buildLargest(List<Integer> codes) {
        List<String> parts = new ArrayList<>();
        for (int c : codes) {
            parts.add(Integer.toString(c));
        }
        // Compare a+b vs b+a; equal length so string compare == numeric compare.
        parts.sort((a, b) -> (b + a).compareTo(a + b));
        // All-zeros guard: if the biggest piece is "0", the whole thing is 0.
        if (!parts.isEmpty() && parts.get(0).equals("0")) {
            log.info(() -> "All zeros → \"0\"");
            return "0";
        }
        String result = String.join("", parts);
        log.info(() -> "Largest identifier = " + result);
        return result;
    }
}
