package com.bank.largestnumber;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: largest identifier from branch codes.
public class LargestNumberDemo {
    private static final Logger log = Logger.getLogger(LargestNumberDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        LargestNumberBuilder builder = new LargestNumberBuilder();

        // Branch codes to concatenate into the largest identifier.
        List<Integer> codes = List.of(3, 30, 34, 5, 9);
        String id = builder.buildLargest(codes);
        log.info(() -> "Priority identifier = " + id);

        // All-zeros case.
        List<Integer> zeros = List.of(0, 0);
        log.info(() -> "Zeros case = " + builder.buildLargest(zeros));
    }
}
